 generate.append(el('p','fine-print','演示使用内置 Mochi 样例，不上传原图，不调用 AI。'));
 retained.prompt.querySelector('.field-label').textContent='动作描述 · Direction';retained.prompt.querySelector('.field-hint').textContent='描述动作，以及哪些部位应保持不动。';retained.count.querySelector('.field-hint').textContent='用于下次生成；姿势越多，细节可能越少。';
 const imports=el('div','creation-alternatives');move(imports,'#import-frames','#build-motion');imports.querySelector('#build-motion').textContent='本地动作';imports.querySelector('#build-motion').className='button button-outline full';imports.querySelector('#import-frames').textContent='导入姿势';
 const more=el('div','generation-utilities');move(more,'#recover-ai','#check-ai');more.querySelector('#recover-ai').textContent='恢复图集';more.querySelector('#recover-ai').title='恢复最近保存的图集并修正构图，不发起新的生成请求';more.querySelector('#recover-ai').className='button button-outline';generate.querySelector('#generate-ai').after(more);
 const interaction=group('触发方式 · When to play',retained.trigger);interaction.classList.add('interaction-settings');retained.trigger.hidden=true;
 const trigger=retained.trigger.querySelector('select'),tiles=el('div','interaction-tiles');tiles.setAttribute('role','group');tiles.setAttribute('aria-label','触发方式 · When to play');
