 for(const [value,label] of Object.entries(TRIGGERS)){
  const tile=button('',()=>{trigger.value=value;change(trigger);sync()},'interaction-tile');tile.dataset.trigger=value;tile.setAttribute('aria-label',shortLabels[value]);tile.title=shortLabels[value];
  const icon=el('img','interaction-icon');icon.src=INTERACTION_ICONS[value];icon.alt='';icon.width=40;icon.height=40;tile.append(icon,el('span','',shortLabels[value]));tiles.append(tile);
 }
 function sync(){for(const tile of tiles.children)tile.setAttribute('aria-pressed',String(tile.dataset.trigger===trigger.value))}
