 inspector.replaceChildren(generate,imports,interaction);
 document.body.dataset.animationState=has?'review':'create';
 // Naming belongs to the animation, rather than an unrelated tools menu.

 // Nodes removed by replaceChildren remain available through their retained parents.

 // Retain the existing model controls and event handlers; visual controls dispatch their changes.
 const backing=el('div');backing.hidden=true;backing.append(locks);if(loop)backing.append(loop);if(reuse)backing.append(reuse);timeline.append(backing);
 const timelineHead=$('.timeline-header');timelineHead.querySelector('b').textContent='时间轴 · Timeline';timelineHead.querySelector('span').textContent=has?a.frames.length+' 帧 · '+(a.frames.reduce((sum,_,i)=>sum+frameDuration(a,i),0)/1000).toFixed(2)+'s':'设置动作的开始与结束';
 timeline.querySelectorAll(':scope > p').forEach(n=>n.remove());

 retained.playback.hidden=true;
 const modeControl=el('div','transport-mode'),modeOptions=el('div','playback-options');
 modeControl.append(el('span','field-label','播放模式'),modeOptions);modeOptions.setAttribute('role','radiogroup');modeOptions.setAttribute('aria-label','播放模式');
 const modeSelect=retained.playback.querySelector('select');
 for(const [value,label] of [['once','单次'],['loop','循环'],['state','分段']]){
  const option=button(label,()=>{
   if(value===modeSelect.value)return;
   const previous=(modeOptions.querySelector('.playback-indicator')||modeOptions.querySelector('[aria-checked=true]'))?.getBoundingClientRect();
   modeSelect.value=value;change(modeSelect);
   if(!modeSelect.isConnected)animatePlaybackSelection(previous);
   if(modeSelect.isConnected)modeSelect.value=a.playback;
   document.querySelector('[data-play-mode="'+value+'"]')?.focus({preventScroll:true});
  },'playback-option');
  option.dataset.playMode=value;option.setAttribute('role','radio');option.setAttribute('aria-checked',String(value===a.playback));option.tabIndex=value===a.playback?0:-1;modeOptions.append(option);
 }
 modeOptions.onkeydown=e=>{
  const choices=[...modeOptions.children],index=choices.indexOf(e.target);
  const next=e.key==='ArrowRight'||e.key==='ArrowDown'?(index+1)%3:e.key==='ArrowLeft'||e.key==='ArrowUp'?(index+2)%3:e.key==='Home'?0:e.key==='End'?2:-1;
  if(index<0||next<0)return;e.preventDefault();choices[next].click();
 };
 backing.append(retained.playback);

 for(const option of retained.playback.querySelectorAll('option'))option.textContent=({once:'单次',loop:'循环',state:'分段'})[option.value];
 retained.duration.hidden=true;backing.append(retained.duration);
 const durationControl=el('label','transport-duration');durationControl.append(el('span','field-label','时长 · Duration'));
 const durationLine=el('span','duration-value'),seconds=el('input','input');seconds.id='duration-seconds';seconds.type='number';seconds.min=.6;seconds.max=6;seconds.step=.1;seconds.value=a.duration/1000;seconds.setAttribute('aria-label','基础时长（秒） · Duration in seconds');seconds.title='每段动作的基础时长；单帧停留倍数可延长实际时长';
 seconds.onchange=()=>{if(!seconds.checkValidity()||!seconds.value){seconds.value=a.duration/1000;return}$('#duration').value=Math.round(Number(seconds.value)*1000);change($('#duration'))};durationLine.append(seconds,el('span','','s'));durationControl.append(durationLine);
 $('#preview-exit').before(modeControl,durationControl);
 retained.duration.querySelector('.field-label').firstChild.textContent='基础时长 · Duration · ';retained.duration.querySelector('.field-hint').textContent='保存的基础时长；单帧停留可延长实际播放时间。';
 $('#speed').setAttribute('aria-label','仅调整预览速度');$('#speed').title='仅改变预览速度，不影响导出的时长';const speedLabel=el('label','preview-speed');speedLabel.append(el('span','preview-speed-label','速度'));$('#speed').before(speedLabel);speedLabel.append($('#speed'));

 function endpoint(which,host){const input=which==='first'?$('#lock-start'):$('#lock-end');const active=input.checked;const b=button(active?'原图':'使用原图',()=>{input.checked=!active;change(input);document.querySelector('[data-endpoint="'+which+'"]')?.focus()},'endpoint-lock');const icon=document.createElementNS('http://www.w3.org/2000/svg','svg');icon.setAttribute('viewBox','0 0 16 16');icon.setAttribute('aria-hidden','true');icon.innerHTML='<path d="M4 7V5a4 4 0 0 1 8 0'+(active?'v2':'')+'M3 7h10v7H3zM8 10v2"/>';b.prepend(icon);b.dataset.endpoint=which;b.setAttribute('aria-pressed',String(active));b.setAttribute('aria-label',(active?'解锁':'使用原图作为')+(which==='first'?'首帧':'尾帧'));b.title=active?'解锁此端点后即可编辑':has?'用已确认原图替换此端点，可以撤销。':'在此端点加入已确认原图';host.append(b)}
 if(has){
  [...rail.querySelectorAll('[data-frame]')].forEach((b,i)=>{const cell=el('div','frame-cell');b.before(cell);cell.append(b);const small=b.querySelector('small');small.remove();const tick=el('span','frame-tick',String(i+1).padStart(2,'0'));tick.setAttribute('aria-hidden','true');cell.append(tick);b.setAttribute('aria-pressed',String(i===frame));const swap=button('替换',()=>{const left=$('.timeline-scroll')?.scrollLeft||0;b.click();if($('.timeline-scroll'))$('.timeline-scroll').scrollLeft=left;openPosePicker(project,i)},'button button-outline frame-replace');swap.dataset.replaceFrame=i;swap.disabled=lockedFrame(a,i);swap.setAttribute('aria-label','替换第 '+(i+1)+' 帧图像');swap.title=swap.disabled?'请先解锁此原图帧':'替换此帧图像';cell.append(swap);if(i===0)endpoint('first',cell);if(i===a.frames.length-1)endpoint('last',cell)});
 }else{
  rail.classList.add('empty-timeline');for(const which of ['first','last']){const cell=el('div','endpoint-placeholder');cell.append(el('span','',which==='first'?'首帧 · First':'尾帧 · Last'));const img=el('img');img.src=project.reference.image;img.alt='已确认原图 · Original';cell.append(img);endpoint(which,cell);rail.append(cell);if(which==='first')rail.append(el('p','','生成的姿势会显示在这里'))}
 }
 if(has&&a.playback!=='once'){
  const region=el('section','loop-region');region.setAttribute('aria-label','循环范围 · Loop range');const track=el('div','phase-track');const summary=el('output','loop-summary');
  const sliders=el('div','loop-handles');const handles=[];
  const draw=()=>{const start=+handles[0].value,end=+handles[1].value;track.replaceChildren();for(const [count,label,cls] of [[start,'进入 · Entry','entry'],[end-start+1,'循环 · Loop','loop'],[a.frames.length-end-1,'退出 · Exit','exit']]){if(!count)continue;const segment=el('span',cls,label);segment.style.flex=count;track.append(segment)}summary.textContent='循环：第 '+(start+1)+'–'+(end+1)+' 帧 · 拖动手柄或使用方向键';};
  for(const [key,label,value] of [['start','循环首帧',a.loopStart],['end','循环尾帧',a.loopEnd]]){const range=el('input','loop-handle '+key);range.type='range';range.min=0;range.max=a.frames.length-1;range.step=1;range.value=value;range.setAttribute('aria-label',label);range.oninput=()=>{range.value=key==='start'?Math.min(+range.value,+handles[1].value):Math.max(+range.value,+handles[0].value);draw()};range.onchange=()=>{const target=$('#loop-'+key);target.value=range.value;change(target);document.querySelector('.loop-handle.'+key)?.focus()};handles.push(range);sliders.append(range)}
  region.append(track,sliders,summary);timeline.append(region);draw();
 }
 if(has){
  const selection=el('section','selected-frame-tools');selection.setAttribute('aria-label','当前帧工具');selection.append(el('h3','','当前帧 · '+(frame+1)+(lockedFrame(a,frame)?' · 锁定原图':'')));selection.append(tools);
  const dock=el('div','frame-tools-dock'),handle=button('',null,'frame-tools-handle');
  const chevron=el('span','frame-tools-chevron');chevron.setAttribute('aria-hidden','true');handle.append(chevron);handle.title='当前帧工具';
  selection.id='frame-tools-panel';handle.setAttribute('aria-controls',selection.id);handle.setAttribute('aria-label','当前帧工具 · Frame tools');
  let hovered=false,pinned=false,suppressFocus=false;
  const show=open=>{dock.dataset.open=String(open);handle.setAttribute('aria-expanded',String(open));selection.inert=!open};
  const sync=()=>show(hovered||pinned||selection.contains(document.activeElement));
  dock.onpointerenter=e=>{if(e.pointerType!=='touch'){hovered=true;sync()}};
  dock.onpointerleave=()=>{hovered=false;sync()};
  dock.onfocusin=()=>{if(!suppressFocus)show(true)};
  dock.onfocusout=()=>queueMicrotask(sync);
  handle.onclick=()=>{pinned=!pinned;show(pinned||hovered)};
  dock.onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();hovered=false;pinned=false;suppressFocus=true;handle.focus({preventScroll:true});suppressFocus=false;show(false)}};
  dock.append(handle,selection);show(false);$('#animation-stage').prepend(dock);$('#animation-stage').classList.add('has-frame-tools');
  $('#frame-left').disabled=lockedFrame(a,frame)||frame===0||lockedFrame(a,frame-1);$('#frame-right').disabled=lockedFrame(a,frame)||frame===a.frames.length-1||lockedFrame(a,frame+1);$('#frame-repeat').textContent='复制';$('#frame-remove').textContent='删除';$('#frame-repair').textContent='修复';$('#frame-original').textContent='替换为原图';
  backing.append($('#frame-original'));
  const hold=$('#frame-hold');const holdLabel=hold.closest('label');holdLabel.firstChild.textContent='停留 ';
  hold.setAttribute('aria-label','当前帧停留倍数');hold.title='相对于基础时长除以帧数的倍率';
  holdLabel.title='停留倍率调整当前帧的相对时长；基础时长和帧数也会影响播放。';$('#frame-left').setAttribute('aria-label','向前移动当前帧');$('#frame-right').setAttribute('aria-label','向后移动当前帧');

  const lockHint=el('p','fine-print','在时间轴解锁首尾帧后可编辑。');lockHint.hidden=!lockedFrame(a,frame);selection.append(lockHint);
 }
 const scroll=el('div','timeline-scroll'),track=el('div','timeline-track');if(has)track.style.minWidth=(a.frames.length*104+(a.frames.length-1)*8)+'px';rail.before(scroll);scroll.append(track);track.append(rail);timeline.prepend($('.stage-foot'));$('.stage-foot').classList.add('timeline-transport');const region=timeline.querySelector('.loop-region');if(region)scroll.after(region);
 const footer=el('div','timeline-review');const secondary=el('div','review-tools');move(secondary,undo);footer.append(secondary);approve.disabled=!has;approve.textContent=a.approved?'试玩 →':'确认动画';approve.classList.remove('full');footer.append(approve);timeline.append(footer);
