function openPosePicker(project,frame){
 const scrollLeft=$('.timeline-scroll')?.scrollLeft||0;
 const dialog=el('dialog','pose-picker');dialog.setAttribute('aria-label','选择姿势 · Choose a pose');const head=el('header','dialog-head');head.append(el('h2','','选择姿势 · Choose a pose'),button('关闭 · Close ×',()=>closeMotionDialog(dialog)));dialog.append(head,el('p','muted','用原图或已有姿势替换第 '+(frame+1)+' 帧。'));
 const original=button('',()=>{closeMotionDialog(dialog);$('#frame-original').click()},'button button-outline pose-original');const originalImage=el('img');originalImage.src=project.reference.image;originalImage.alt='';original.append(originalImage,el('span','','使用原图 · Original'));dialog.append(original);
 for(const [id,a] of Object.entries(project.actions)){if(!a.frames.length)continue;dialog.append(el('h3','',actionLabel(project,id)));const grid=el('div','pose-picker-grid');a.frames.forEach((src,i)=>{const b=button('',()=>{const select=$('#frame-source');select.value=id+':'+i;closeMotionDialog(dialog);$('#frame-reuse').click()});const img=el('img');img.src=src;img.alt='';b.append(img,el('span','','帧 '+(i+1)));b.dataset.poseSource=id+':'+i;b.setAttribute('aria-label',actionLabel(project,id)+'，帧 '+(i+1));grid.append(b)});dialog.append(grid)}
 dialog.onclose=()=>{dialog.remove();if($('.timeline-scroll'))$('.timeline-scroll').scrollLeft=scrollLeft;document.querySelector('[data-replace-frame="'+frame+'"]')?.focus({preventScroll:true})};document.body.append(dialog);openMotionDialog(dialog);
}

// Embedded originals keep the local static allowlist unchanged. Source PNGs: assets/interaction-icons/.
const INTERACTION_ICONS={"manual":"data:image/png;base64,","idle":"data:image/png;base64,","click":"data:image/png;base64,","hold":"data:image/png;base64,","drag":"data:image/png;base64,"};

// Original generated PNGs: assets/playground-icons/.
const PLAYGROUND_ICONS={"pet":"data:image/png;base64,","feed":"data:image/png;base64,","sleep":"data:image/png;base64,","focus":"data:image/png;base64,"};

// Apply the Remix scene transition only to the preview, leaving the tab strip and tools steady.
export function createAnimationTabTransition({getPreview,media=window.matchMedia('(prefers-reduced-motion: reduce)')}){
 let serial=0,pending=null;
 const animations=new Set(),easing='cubic-bezier(0,0,0,1)';
 function cancel(){serial++;pending=null;for(const animation of animations)animation.cancel();animations.clear()}
 function animate(frames,duration){
  const preview=getPreview();if(media.matches||!preview?.animate)return Promise.resolve();
  const animation=preview.animate(frames,{duration,easing,fill:'both'});animations.add(animation);
  return animation.finished.catch(()=>{}).finally(()=>{animation.cancel();animations.delete(animation)});
 }
 function complete(){
  if(!pending)return;
  const {commit,direction}=pending;pending=null;
  commit();
  if(!media.matches)void animate([{opacity:0,transform:'translateX('+direction*8+'px)'},{opacity:1,transform:'translateX(0)'}],200);
 }
 async function switchTo(commit,direction=1){
  cancel();const run=serial;pending={commit,direction};
  if(media.matches||!getPreview()?.animate){complete();return}
  await animate([{opacity:1,transform:'translateX(0)'},{opacity:0,transform:'translateX('+(-direction*8)+'px)'}],100);
  if(run===serial)complete();
 }
 media.addEventListener('change',()=>{if(media.matches){const next=pending;cancel();pending=next;complete()}});
 return {switchTo,cancel};
}


// Shared UI motion; artwork playback and project data remain independent.
const uiAnimations=new WeakMap(),dialogMotion=new WeakMap();
const motionReduced=()=>globalThis.matchMedia?.('(prefers-reduced-motion: reduce)').matches??false;
export function animateUI(node,keyframes,duration=250){
 if(!node)return Promise.resolve();
 uiAnimations.get(node)?.cancel();
 if(motionReduced()||!node.animate)return Promise.resolve();
 const animation=node.animate(keyframes,{duration,easing:'cubic-bezier(0,0,0,1)',fill:'both'});
 uiAnimations.set(node,animation);
 const media=globalThis.matchMedia?.('(prefers-reduced-motion: reduce)');
 const settle=()=>{if(media.matches)animation.finish()};
 media?.addEventListener('change',settle);
 return animation.finished.catch(()=>{}).finally(()=>{
  animation.cancel();if(uiAnimations.get(node)===animation)uiAnimations.delete(node);
  media?.removeEventListener('change',settle);
 });
}
function motionDialogState(dialog){
 let state=dialogMotion.get(dialog);if(state)return state;
 state={run:0,closing:null};dialogMotion.set(dialog,state);
 dialog.addEventListener('cancel',event=>{event.preventDefault();void closeMotionDialog(dialog)});
 dialog.addEventListener('close',()=>{if(!dialog.open){state.run++;dialog.inert=false;dialog.classList.remove('pf-dialog-motion','pf-dialog-closing');uiAnimations.get(dialog)?.cancel()}});
 return state;
}
export function openMotionDialog(dialog){
 const state=motionDialogState(dialog);state.run++;state.closing=null;
 uiAnimations.get(dialog)?.cancel();dialog.inert=false;
 dialog.classList.remove('pf-dialog-closing');dialog.classList.add('pf-dialog-motion');
 if(!dialog.open)dialog.showModal();
 return animateUI(dialog,[{opacity:0,transform:'translateY(18px) scale(.94)'},{opacity:1,transform:'translateY(0) scale(1)'}],250);
}
export function closeMotionDialog(dialog){
 const state=motionDialogState(dialog);
 if(state.closing)return state.closing;
 if(!dialog.open)return Promise.resolve();
 const run=++state.run;
 dialog.inert=true;dialog.classList.add('pf-dialog-closing');
 const finish=()=>{if(run!==state.run)return;dialog.inert=false;dialog.close();dialog.classList.remove('pf-dialog-motion','pf-dialog-closing');state.closing=null};
 if(motionReduced()||!dialog.animate){finish();return Promise.resolve()}
 const css=getComputedStyle(dialog);
 state.closing=animateUI(dialog,[{opacity:css.opacity,transform:css.transform},{opacity:0,transform:'translateY(8px) scale(.97)'}],200).then(finish);
 return state.closing;
}
export function animateTabSelection(previous){
 const strip=document.querySelector('.animation-tab-strip'),selected=strip?.querySelector('.animation-browser-tab.active');
 if(!previous||!selected||motionReduced())return;
 const rect=selected.getBoundingClientRect(),parent=strip.getBoundingClientRect();
 const marker=document.createElement('span');marker.className='pf-tab-indicator';marker.setAttribute('aria-hidden','true');
 strip.classList.add('pf-tabs-moving');strip.append(marker);
 const x=rect.left-parent.left+strip.scrollLeft,from=previous.left-parent.left+strip.scrollLeft;
 marker.style.width=rect.width+'px';marker.style.transform='translateX('+x+'px)';
 void animateUI(marker,[{transform:'translateX('+from+'px)',width:previous.width+'px'},{transform:'translateX('+x+'px)',width:rect.width+'px'}],300).finally(()=>{marker.remove();strip.classList.remove('pf-tabs-moving')});
}


function animatePlaybackSelection(previous){
 const group=document.querySelector('.playback-options'),selected=group?.querySelector('[aria-checked=true]');
 if(!previous||!selected||motionReduced())return;
 const rect=selected.getBoundingClientRect(),parent=group.getBoundingClientRect();
 const marker=el('span','playback-indicator');marker.setAttribute('aria-hidden','true');
 const x=rect.left-parent.left-group.clientLeft,y=rect.top-parent.top-group.clientTop;
 marker.style.left=x+'px';marker.style.top=y+'px';marker.style.width=rect.width+'px';marker.style.height=rect.height+'px';
 group.classList.add('playback-moving');group.append(marker);
 void animateUI(marker,[{transform:'translateX('+(previous.left-rect.left)+'px)',width:previous.width+'px'},{transform:'translateX(0)',width:rect.width+'px'}],300).finally(()=>{marker.remove();group.classList.remove('playback-moving')});
}

export function compactActionLabel(project,id){const label=actionLabel(project,id);return /^(待机|开心|进食|睡眠) · (Idle|Happy|Eating|Sleeping)$/.test(label)?label.split(' · ')[0]:label}

export function createFrameWheelHandler({getIndex,getCount,select,now=()=>performance.now()}){
 let sum=0,lastEvent=-Infinity,lastStep=-Infinity,direction=0;
 return event=>{
  if(event.ctrlKey||event.metaKey||event.altKey||event.shiftKey||Math.abs(event.deltaX)>Math.abs(event.deltaY)||!event.deltaY)return;
  if(event.target?.closest?.('input,select,textarea,[contenteditable=true]'))return;
  const step=Math.sign(event.deltaY),index=getIndex(),count=getCount();
  if(count<2||index+step<0||index+step>=count){sum=0;return}
  const time=now();
  if(time-lastEvent>180||step!==direction)sum=0;
  lastEvent=time;direction=step;
  event.preventDefault();
  sum+=event.deltaY*(event.deltaMode===1?16:event.deltaMode===2?320:1);
  if(Math.abs(sum)<32||time-lastStep<90)return;
  sum=0;lastStep=time;select(index+step);
 };
}
